"""Compare the OpenAPI document generated by the Go server (Huma) with the shared
T003 contract. Usage: python scripts/contracts/compare.py [generated.json]

Without an argument the script runs `go run ./cmd/ctl openapi` in apps/server.
Exit status is nonzero when the generated API disagrees with the contract in a
way not listed in DEVIATIONS or amendments.json. DEVIATIONS are intentional,
policy-compatible differences that are documented in handoffs/T003.md;
amendments.json lists later API changes and the ADR behind each.
"""
import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
CONTRACT = json.loads((ROOT / 'contracts' / 't003' / 'openapi.json').read_text(encoding='utf-8'))
# T004 additions live in their own contract file and share T003 components.
_t4 = ROOT / 'contracts' / 't004' / 'openapi.json'
if _t4.exists():
    _extra = json.loads(_t4.read_text(encoding='utf-8'))
    for _p, _item in _extra['paths'].items():
        assert _p not in CONTRACT['paths'] or not set(_item) & set(CONTRACT['paths'][_p]), f'T004 contract overlaps T003 at {_p}'
        CONTRACT['paths'].setdefault(_p, {}).update(_item)
    for _n, _sch in _extra['components']['schemas'].items():
        assert _n not in CONTRACT['components']['schemas'], f'T004 schema {_n} collides with T003'
        CONTRACT['components']['schemas'][_n] = _sch

# T005 additions (editions, reading state, shelves, repair). Routes are merged as
# they are implemented; every other T005 operation is listed as PENDING and its
# schemas are compared only when an implemented operation reaches them. Never
# drop a route from the contract to make this pass: add it to IMPLEMENTED_T005.
IMPLEMENTED_T005 = {'listTitles', 'searchTitles', 'previewTitleCover', 'getCoverSettings', 'setCoverSettings', 'getTitleCover', 'putTitleCover', 'searchTitleCovers', 'setTitleCoverFromUrl', 'regenerateTitleCover', 'getTitleCovers', 'getTitle', 'listTitleRecordings', 'listEditions', 'getEdition', 'getReaderSnapshot',
                    'getReadingPosition', 'writeReadingPosition', 'getReadingCompletion', 'writeReadingCompletion',
                    'getReadingHistory', 'listPersonalConflicts', 'resolvePersonalConflict',
                    'listAnnotations', 'getAnnotation', 'putAnnotation', 'deleteAnnotation',
                    'listShelves', 'getShelf', 'putShelf', 'deleteShelf', 'getShelfTitles', 'addShelfTitle', 'removeShelfTitle',
                    'orderShelfTitles',
                    'linkEditionTitle', 'getEditionMetadata', 'setEditionMetadata', 'removeEditionMetadata',
                    'getComicPages', 'prepareComicPages', 'getComicPage', 'headComicPage',
                    'planRecordingRepair', 'getRecordingRepair', 'approveRecordingRepair', 'executeRecordingRepair', 'cancelRecordingRepair'}
PENDING_T005 = []
_t5 = ROOT / 'contracts' / 't005' / 'openapi.json'
if _t5.exists():
    _x = json.loads(_t5.read_text(encoding='utf-8'))
    _x_paths = {}
    for _p, _item in _x['paths'].items():
        for _m, _o in _item.items():
            if _o['operationId'] in IMPLEMENTED_T005:
                _x_paths.setdefault(_p, {})[_m] = _o
            else:
                PENDING_T005.append(_o['operationId'])
    # T005Conflict.candidate lists every personal-state write kind. Members whose
    # resource kinds are not implemented yet are dropped from the compared copy;
    # remove a name here in the same change that implements its conflicts.
    PENDING_CANDIDATES = set()
    _cand = _x['components']['schemas']['T005Conflict']['properties']['candidate']
    _cand['oneOf'] = [m for m in _cand['oneOf'] if m['$ref'].rsplit('/', 1)[-1] not in PENDING_CANDIDATES]
    _seen, _stack = set(), []

    def _walk(node):
        if isinstance(node, dict):
            for _k, _v in node.items():
                if _k == '$ref':
                    _n = _v.rsplit('/', 1)[-1]
                    if _n not in _seen:
                        _seen.add(_n)
                        _stack.append(_n)
                else:
                    _walk(_v)
        elif isinstance(node, list):
            for _v in node:
                _walk(_v)

    _walk(_x_paths)
    while _stack:
        _walk(_x['components']['schemas'][_stack.pop()])
    for _p, _item in _x_paths.items():
        assert _p not in CONTRACT['paths'] or not set(_item) & set(CONTRACT['paths'][_p]), f'T005 contract overlaps at {_p}'
        CONTRACT['paths'].setdefault(_p, {}).update(_item)
    for _n in sorted(_seen):
        if _n in CONTRACT['components']['schemas']:
            raise SystemExit(f'T005 schema {_n} collides with an earlier contract')
        CONTRACT['components']['schemas'][_n] = _x['components']['schemas'][_n]
    PENDING_T005_SCHEMAS = sorted(set(_x['components']['schemas']) - _seen)

# T006 management additions (integrations, SMTP delivery, KOReader management).
# Merged as implemented; every other operation is reported PENDING and its
# schemas are compared only once an implemented operation reaches them. Never
# drop a route from the contract to make this pass: add it to IMPLEMENTED_T006.
# The root-mounted OPDS/KOReader wire operations (protocols.openapi.json) are not
# Huma routes; they are verified by wire tests, not by this comparison.
IMPLEMENTED_T006 = {'getIntegrationSettings', 'setIntegrationSettings', 'listIntegrationCredentials',
                    'createIntegrationCredential', 'revokeIntegrationCredential',
                    'getKoReaderPosition', 'listKoReaderBindings', 'putKoReaderBinding', 'deleteKoReaderBinding',
                    'listKoReaderConflicts', 'resolveKoReaderConflict', 'reapplyKoReaderConflict',
                    'getPersonalSmtp', 'setPersonalSmtp', 'testPersonalSmtp', 'getServerSmtp', 'setServerSmtp', 'testServerSmtp',
                    'listDeliveryTransports', 'listDeliveryRecipients', 'putDeliveryRecipient', 'deleteDeliveryRecipient',
                    'listDeliveries', 'createDelivery', 'getDelivery', 'cancelDelivery'}
PENDING_T006 = []
PENDING_T006_SCHEMAS = []
_t6 = ROOT / 'contracts' / 't006' / 'openapi.json'
if _t6.exists():
    _y = json.loads(_t6.read_text(encoding='utf-8'))
    _y_paths = {}
    for _p, _item in _y['paths'].items():
        for _m, _o in _item.items():
            if _o['operationId'] in IMPLEMENTED_T006:
                _y_paths.setdefault(_p, {})[_m] = _o
            else:
                PENDING_T006.append(_o['operationId'])
    _seen6, _stack6 = set(), []

    def _walk6(node):
        if isinstance(node, dict):
            for _k, _v in node.items():
                if _k == '$ref':
                    _n = _v.rsplit('/', 1)[-1]
                    if _n not in _seen6:
                        _seen6.add(_n)
                        _stack6.append(_n)
                else:
                    _walk6(_v)
        elif isinstance(node, list):
            for _v in node:
                _walk6(_v)

    _walk6(_y_paths)
    while _stack6:
        _walk6(_y['components']['schemas'][_stack6.pop()])
    for _p, _item in _y_paths.items():
        assert _p not in CONTRACT['paths'] or not set(_item) & set(CONTRACT['paths'][_p]), f'T006 contract overlaps at {_p}'
        CONTRACT['paths'].setdefault(_p, {}).update(_item)
    for _n in sorted(_seen6):
        if _n in CONTRACT['components']['schemas']:
            raise SystemExit(f'T006 schema {_n} collides with an earlier contract')
        CONTRACT['components']['schemas'][_n] = _y['components']['schemas'][_n]
    PENDING_T006_SCHEMAS = sorted(set(_y['components']['schemas']) - _seen6)

# T009 additions (ADR-0081): book details and personal rating, review and dates. Every operation is implemented.
_t9 = ROOT / 'contracts' / 't009' / 'openapi.json'
if _t9.exists():
    _z = json.loads(_t9.read_text(encoding='utf-8'))
    for _p, _item in _z['paths'].items():
        assert _p not in CONTRACT['paths'] or not set(_item) & set(CONTRACT['paths'][_p]), f'T009 contract overlaps at {_p}'
        CONTRACT['paths'].setdefault(_p, {}).update(_item)
    for _n, _sch in _z['components']['schemas'].items():
        if _n in CONTRACT['components']['schemas']:
            raise SystemExit(f'T009 schema {_n} collides with an earlier contract')
        CONTRACT['components']['schemas'][_n] = _sch

# The contract files keep the names they were agreed under, which carry task IDs. The server publishes neutral names,
# listed in schema_names.json, so translate the merged contract before comparing.
SCHEMA_NAMES = json.loads((ROOT / 'scripts' / 'contracts' / 'schema_names.json').read_text(encoding='utf-8'))


def published(node):
    if isinstance(node, dict):
        return {k: published(v) for k, v in node.items()}
    if isinstance(node, list):
        return [published(v) for v in node]
    if isinstance(node, str) and node.startswith('#/components/schemas/'):
        prefix, name = node.rsplit('/', 1)
        return f'{prefix}/{SCHEMA_NAMES.get(name, name)}'
    return node


CONTRACT = published(CONTRACT)
CONTRACT['components']['schemas'] = {SCHEMA_NAMES.get(n, n): s for n, s in CONTRACT['components']['schemas'].items()}

# ADR-0107 (supersedes the smart shelf grammar in contracts/t005): a smart shelf filter is the library search
# TitleFilter, which also gained the "tag" field. Apply that to the merged contract before comparing.
for _name in ('ShelfFilter', 'ShelfFilterGroup', 'ShelfFilterNot', 'ShelfPredicate'):
    CONTRACT['components']['schemas'].pop(_name, None)
for _branch in CONTRACT['components']['schemas']['ShelfData']['properties']['filter'].get('anyOf', []):
    if _branch.get('$ref', '').endswith('/ShelfFilter'):
        _branch['$ref'] = '#/components/schemas/TitleFilter'
CONTRACT['components']['schemas']['TitleFilter']['properties']['field']['enum'].append('tag')

if len(sys.argv) > 1:
    GENERATED = json.loads(Path(sys.argv[1]).read_text(encoding='utf-8'))
else:
    out = subprocess.run(['go', 'run', './cmd/ctl', 'openapi'], cwd=ROOT / 'apps' / 'server', check=True,
                         capture_output=True, text=True).stdout
    GENERATED = json.loads(out)

# Intentional differences. Key: where, value: reason.
DEVIATIONS = {
    'UpdateUser.minProperties': 'enforced by the handler (422 validation_failed); Huma has no minProperties tag',
    'Problem.additionalProperties': 'Problem is a closed typed struct in Huma; the contract leaves it open',
}

errors, notes = [], []


def ref_name(ref):
    return ref.rsplit('/', 1)[-1]


def resolve(spec, schema):
    while isinstance(schema, dict) and '$ref' in schema:
        schema = spec['components']['schemas'][ref_name(schema['$ref'])]
    return schema


IGNORED = {'description', 'title', 'examples', 'example', '$schema', 'default', 'readOnly', 'x-', 'contentEncoding'}


def norm(spec, schema, depth=0, seen=()):
    """Reduce a schema to a comparable structure; $ref names are kept for objects. A schema that refers back to
    itself (a recursive filter tree) is reduced to its name where the cycle closes."""
    if schema is None:
        return None
    ref = ref_name(schema['$ref']) if isinstance(schema, dict) and '$ref' in schema else None
    if ref and ref in seen:
        return {'$name': ref, 'recursive': True}
    if ref:
        seen = seen + (ref,)
    s = resolve(spec, schema)
    out = {}
    nullable = bool(s.get('nullable'))
    if 'anyOf' in s:
        non_null = [x for x in s['anyOf'] if resolve(spec, x).get('type') != 'null']
        has_null = len(non_null) != len(s['anyOf'])
        if has_null and len(non_null) == 1:
            inner = norm(spec, non_null[0], depth, seen)
            inner['nullable'] = True
            return inner
        out['anyOf'] = [norm(spec, x, depth + 1, seen) for x in s['anyOf']]
    t = s.get('type')
    if isinstance(t, list):
        if 'null' in t:
            nullable = True
        t = [x for x in t if x != 'null']
        t = t[0] if len(t) == 1 else t
    if t:
        out['type'] = t
    if nullable:
        out['nullable'] = True
    if 'const' in s:
        out['enum'] = [s['const']]
    if 'enum' in s:
        out['enum'] = sorted(x for x in s['enum'] if x is not None)
    for k in ('format', 'pattern', 'minimum', 'maximum', 'minLength', 'maxLength', 'minItems', 'minProperties'):
        if k in s and not (k in ('minLength', 'minItems') and s[k] == 0):  # a zero lower bound is vacuous
            out[k] = s[k]
    if out.get('format') in ('int64', 'int32', 'double', 'float'):
        del out['format']
    if 'properties' in s:
        out['properties'] = {k: norm(spec, v, depth + 1, seen) for k, v in s['properties'].items()}
        out['required'] = sorted(s.get('required', []))
        out['additionalProperties'] = s.get('additionalProperties', None)
    if 'items' in s:
        out['items'] = norm(spec, s['items'], depth + 1, seen)
    if ref and depth > 0:
        out['$name'] = ref
    return out


def compare(path, want, got):
    """The contract (want) decides which keys matter; extra generated keys are tolerated."""
    if want is None:
        return
    if got is None:
        errors.append(f'{path}: missing in generated spec')
        return
    for k, v in want.items():
        if k == '$name':
            continue
        if k == 'additionalProperties':
            if v is False and got.get(k) is not False:
                errors.append(f'{path}: contract forbids extra properties, generated allows them')
            elif v in (True, None) and got.get(k) is False and path.split('.')[0] + '.additionalProperties' not in DEVIATIONS:
                errors.append(f'{path}: generated forbids extra properties, contract allows them')
            continue
        if k == 'minProperties' and path + '.minProperties' in DEVIATIONS or (k == 'minProperties' and path.split('.')[0] + '.minProperties' in DEVIATIONS):
            continue
        if k == 'properties':
            if set(v) != set(got.get('properties', {})):
                errors.append(f'{path}: properties differ: contract-only={sorted(set(v) - set(got.get("properties", {})))} generated-only={sorted(set(got.get("properties", {})) - set(v))}')
            for name, sub in v.items():
                compare(f'{path}.{name}', sub, got.get('properties', {}).get(name))
        elif k == 'items':
            compare(path + '[]', v, got.get('items'))
        elif k == 'anyOf':
            if len(v) != len(got.get('anyOf', [])):
                errors.append(f'{path}: anyOf arity differs')
        elif k == 'required':
            if v != got.get('required', []):
                errors.append(f'{path}: required differs: contract={v} generated={got.get("required", [])}')
        elif k == 'nullable':
            if not got.get('nullable'):
                errors.append(f'{path}: contract allows null, generated does not')
        else:
            if got.get(k) != v and f'{path}.{k}' not in DEVIATIONS:  # a documented deviation is reported below, not as an error
                errors.append(f'{path}.{k}: contract={v!r} generated={got.get(k)!r}')


# ---- component schemas -------------------------------------------------------
for name, schema in CONTRACT['components']['schemas'].items():
    if name not in GENERATED['components']['schemas']:
        errors.append(f'schema {name}: missing in generated spec')
        continue
    compare(name, norm(CONTRACT, {'$ref': f'#/components/schemas/{name}'}), norm(GENERATED, {'$ref': f'#/components/schemas/{name}'}))
extra = sorted(set(GENERATED['components']['schemas']) - set(CONTRACT['components']['schemas']))
if extra:
    notes.append(f'generated-only schemas (inline/helper types): {extra}')


# ---- operations -----------------------------------------------------------------
def operations(spec):
    ops = {}
    for p, item in spec['paths'].items():
        for m, o in item.items():
            if m in ('parameters', 'summary', 'description', 'servers'):
                continue
            ops[o['operationId']] = (m.upper(), p, o)
    return ops


want_ops, got_ops = operations(CONTRACT), operations(GENERATED)
for oid in sorted(set(want_ops) - set(got_ops)):
    errors.append(f'operation {oid}: missing in generated spec')
for oid in sorted(set(got_ops) - set(want_ops)):
    errors.append(f'operation {oid}: not in the contract (unexpected route)')


def strip_prefix(path):
    return path[len('/api/v1'):] if path.startswith('/api/v1/') else path


def body_schema(spec, op):
    c = op.get('requestBody', {}).get('content', {})
    for mt in c.values():
        s = mt.get('schema')
        return ref_name(s['$ref']) if s and '$ref' in s else json.dumps(s, sort_keys=True)
    return None


def response_schema(spec, op, code):
    r = op.get('responses', {}).get(code)
    if not r:
        return None
    for mt in r.get('content', {}).values():
        s = mt.get('schema')
        if s and '$ref' in s:
            return ref_name(s['$ref'])
        return json.dumps({k: v for k, v in (s or {}).items() if k in ('type', 'format')}, sort_keys=True)
    return ''


def params(spec, op, item):
    out = {}
    for prm in list(op.get('parameters', [])) + list(item.get('parameters', [])):
        prm = prm if '$ref' not in prm else spec['components']['parameters'][ref_name(prm['$ref'])]
        out[(prm['in'], prm['name'])] = bool(prm.get('required'))
    return out


for oid in sorted(set(want_ops) & set(got_ops)):
    wm, wp, wo = want_ops[oid]
    gm, gp, go = got_ops[oid]
    if wm != gm or wp != strip_prefix(gp):
        errors.append(f'{oid}: {wm} {wp} vs generated {gm} {gp}')
    if body_schema(CONTRACT, wo) != body_schema(GENERATED, go):
        errors.append(f'{oid}: request body {body_schema(CONTRACT, wo)} vs {body_schema(GENERATED, go)}')
    wprm = params(CONTRACT, wo, CONTRACT['paths'][wp])
    gprm = params(GENERATED, go, GENERATED['paths'][gp])
    for k, req in wprm.items():
        if k not in gprm:
            errors.append(f'{oid}: parameter {k} missing')
        elif req and not gprm[k]:
            errors.append(f'{oid}: parameter {k} must be required')
    for k in set(gprm) - set(wprm):
        errors.append(f'{oid}: generated-only parameter {k}')
    for code in wo['responses']:
        if code not in go['responses'] and 'default' not in go['responses']:
            errors.append(f'{oid}: response {code} not declared')
            continue
        if code.startswith('2') and code in go['responses']:
            if response_schema(CONTRACT, wo, code) != response_schema(GENERATED, go, code):
                errors.append(f'{oid}: {code} schema {response_schema(CONTRACT, wo, code)} vs {response_schema(GENERATED, go, code)}')
    if (wo.get('security') or None) and not go.get('security') and not GENERATED.get('security'):
        errors.append(f'{oid}: security requirement missing')

# security schemes
for name, scheme in CONTRACT['components']['securitySchemes'].items():
    if GENERATED['components'].get('securitySchemes', {}).get(name, {}).get('type') != scheme['type']:
        errors.append(f'security scheme {name} differs')

# The contract files record what was agreed for each task. Later accepted decisions have changed the API since, and each
# such difference is listed word for word in amendments.json with its ADR. Anything not listed is still an error, and so
# is a listed difference that no longer occurs. Breaking changes are judged separately by apps/server/internal/apicompat.
AMENDMENTS = {a['difference']: a for a in json.loads((ROOT / 'scripts' / 'contracts' / 'amendments.json').read_text(encoding='utf-8'))['amendments']}
amended = [e for e in errors if e in AMENDMENTS]
errors = [e for e in errors if e not in AMENDMENTS] + [
    f'amendments.json lists a difference that no longer occurs; remove it: {d}' for d in AMENDMENTS if d not in amended]

print(f'T005 pending (not yet implemented, not compared): {len(PENDING_T005)} operations {PENDING_T005}')
print(f'T005 schemas reachable only from pending operations: {len(PENDING_T005_SCHEMAS)}')
print(f'T006 implemented: {len(IMPLEMENTED_T006)} operations; pending (not yet compared): {len(PENDING_T006)} {PENDING_T006}')
print(f'T006 schemas reachable only from pending operations: {len(PENDING_T006_SCHEMAS)}')
print(f'compared {len(want_ops)} operations and {len(CONTRACT["components"]["schemas"])} schemas')
for k, v in DEVIATIONS.items():
    print(f'  intentional deviation {k}: {v}')
print(f'  {len(amended)} difference(s) from the task contracts are authorized by later ADRs (amendments.json)')
for n in notes:
    print('  note:', n)
if errors:
    print(f'{len(errors)} difference(s):')
    for e in errors:
        print('  -', e)
    sys.exit(1)
print('OPENAPI PARITY OK')
